export type Suggestion = {
	id: number
	label: string
	prompt: string
}

const suggestions: Suggestion[] = [
	{
		id: 1,
		label: 'Workout tracker',
		prompt: 'Make a workout tracker app'
	},
	{
		id: 2,
		label: 'Recipe app',
		prompt: 'Make a recipe app'
	},
	{
		id: 3,
		label: 'News reader',
		prompt: 'Make a news reader app'
	},
	{
		id: 4,
		label: 'Travel app',
		prompt: 'Make a travel app'
	}
]

export type ProjectScreenProps = {
	projectGroupId: string
	organizationId: string
	withLiquidGlass: boolean
	isLauncher: boolean
	canUseMAX: boolean
}

export const ProjectScreen = ({
	projectGroupId: initialProjectGroupId,
	organizationId,
	withLiquidGlass,
	isLauncher,
	canUseMAX
}: ProjectScreenProps) => {
	const { bootDevServerAndLaunchApp } =
		useBootServerAndLaunchAppAfterStreaming()
	const reset = useChatStore((state) => state.reset)
	useEffect(() => {
		reset()
	}, [])

	const [projectGroupId, setProjectGroupId] = useState<string>(
		initialProjectGroupId
	)

	useSubscribeToRevisions({
		projectGroupId
	})

	const { handleChat, handleCancel } = useChatMutation({
		projectGroupId
	})

	const insets = useSafeAreaInsets()
	const { theme } = useTheme()
	const [isSpeaking, setIsSpeaking] = useState(false)
	const [prompt, setPrompt] = useState<string>('')
	const [chatAssets, setChatAssets] = useState<string[]>([])
	const [bottomContainerHeight, setBottomContainerHeight] = useState(0)
	const threadId = useThreadId()
	const focusInputRef = useRef<(() => void) | null>(null)

	const setSubmittingCommand = useChatStore(
		(state) => state.setSubmittingCommand
	)
	const setChatState = useChatStore((state) => state.setChatState)
	const { messages, loading: messagesLoading } = useMessagesForChat({
		projectGroupId,
		isNewProjectGroup: projectGroupId !== initialProjectGroupId
	})
	useOnlineStatus()

	// Uncomment to use sample messages for testing
	// const messages = sampleCodePreviewBlock

	const handleSpeechRecognitionStart = () => {
		Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium)
		setIsSpeaking(true)
	}

	const handleSubmit = useCallback(
		async ({
			prompt,
			assetsArray,
			action,
			isThinkingMode
		}: {
			prompt: string
			assetsArray: string[]
			action: ProjectGroupRevisionAction
			isThinkingMode: boolean
		}): Promise<void> => {
			const formattedAssets = assetsArray.map((asset) => `![Image](${asset})`)
			const command = `${prompt}\n${formattedAssets.join('\n')}`
			setPrompt('')
			setChatAssets([])
			setSubmittingCommand({ threadId, command })
			setChatState('PENDING')

			try {
				await handleChat({
					chat: command,
					action,
					isThinkingMode,
					projectGroupId,
					organizationId,
					setProjectGroupId: (newProjectGroupId) => {
						setProjectGroupId(newProjectGroupId)
						if (!isLauncher || !IS_DEV_SERVER) {
							bootDevServerAndLaunchApp({ projectGroupId: newProjectGroupId })
						}
					}
				})
			} catch (error) {
				console.error('Error submitting chat:', error)
				return
			}
		},
		[handleChat, projectGroupId, organizationId, threadId]
	)

	useEffect(() => {
		// this should come from the user app monorepo
		const handleFixError = ({ error }: { error: string }) => {
			handleSubmit({
				prompt: `Fix this error: ${JSON.stringify(error)}`,
				assetsArray: [],
				action: ProjectGroupRevisionAction.CHAT,
				isThinkingMode: false
			})
		}

		errorFixEmitter.on(ErrorFixEvents.ERROR_FIX_SUBMITTED, handleFixError)

		return () => {
			errorFixEmitter.off(ErrorFixEvents.ERROR_FIX_SUBMITTED, handleFixError)
		}
	}, [handleSubmit])

	return (
		<LiquidGlassView
			glassEffectStyle="clear"
			disabled={!withLiquidGlass}
			style={[
				styles.screenContainer(theme),
				{
					backgroundColor: withLiquidGlass
						? 'transparent'
						: colors[theme].background,
					marginBottom: isLauncher ? 10 : 0
				}
			]}
			collapsable={false}
		>
			<View style={styles.container}>
				<AnimatePresence>
					{isSpeaking && (
						<SpeechToTextView
							isSpeaking={isSpeaking}
							setIsSpeaking={setIsSpeaking}
							prompt={prompt}
							setPrompt={setPrompt}
							withLiquidGlass={withLiquidGlass}
							onAfterSubmit={() => {
								focusInputRef.current?.()
							}}
						/>
					)}
				</AnimatePresence>
				<MotiView
					from={{ opacity: 1 }}
					animate={{ opacity: isSpeaking ? 0 : 1 }}
					exit={{ opacity: isSpeaking ? 1 : 0 }}
					transition={{
						duration: 200,
						type: 'timing',
						delay: 50
					}}
					exitTransition={{
						duration: 300,
						type: 'timing',
						delay: 0
					}}
					style={{
						flex: 1,
						padding: withLiquidGlass ? 1 : 0,
						borderRadius: 40
					}}
				>
					{!withLiquidGlass && (
						<View style={{ height: isLauncher ? 24 : 16 + insets.top }}>
							<View
								style={[
									styles.handleBar,
									{ top: isLauncher ? 16 : insets.top }
								]}
							/>
						</View>
					)}
					{messagesLoading && !messages.length ? (
						<View style={styles.loadingContainer}>
							<ActivityIndicator size="large" color={colors[theme].gray[900]} />
						</View>
					) : !!messages.length ? (
						<LiquidGlassView
							disabled={!withLiquidGlass}
							glassEffectStyle="clear"
							style={{ flex: 1 }}
						>
							{!withLiquidGlass && (
								<LinearGradient
									pointerEvents="none"
									colors={[
										`${colors[theme].gray[25]}`,
										`${colors[theme].gray[25]}00`
									]}
									locations={[0.2, 1]}
									style={styles.topGradient}
								/>
							)}
							<ChatStreamContainer
								messages={messages}
								bottomContainerHeight={bottomContainerHeight}
								isLauncher={isLauncher}
							/>
						</LiquidGlassView>
					) : (
						<EmptyState />
					)}
					<Bottom
						shouldShowMessages={!!messages.length}
						suggestions={suggestions}
						handleStart={handleSpeechRecognitionStart}
						handleSubmit={handleSubmit}
						handleCancel={handleCancel}
						chatAssets={chatAssets}
						setChatAssets={setChatAssets}
						prompt={prompt}
						setPrompt={setPrompt}
						bottomContainerHeight={bottomContainerHeight}
						setBottomContainerHeight={setBottomContainerHeight}
						isLauncher={isLauncher}
						canUseMAX={canUseMAX}
						onFocusInput={focusInputRef}
						projectGroupId={projectGroupId}
					/>
					<LinearGradient
						colors={[
							`${colors[theme].gray[25]}00`,
							`${colors[theme].gray[25]}FF`
						]}
						locations={[0, 1]}
						style={styles.bottomFadeGradient}
						pointerEvents="none"
					/>
				</MotiView>
			</View>
		</LiquidGlassView>
	)
}

const styles = defineStyles({
	screenContainer: (theme: Theme) => ({
		flex: 1,
		// backgroundColor: colors[theme].background,
		borderRadius: 40,
		overflow: 'hidden'
	}),
	topGradient: {
		position: 'absolute',
		top: 0,
		left: 0,
		right: 0,
		height: 20,
		zIndex: 1
	},
	container: {
		flex: 1,
		overflow: 'hidden',
		borderRadius: 40
	},
	loadingContainer: {
		flex: 1,
		justifyContent: 'center',
		alignItems: 'center'
	},
	handleBar: {
		position: 'absolute',
		top: 10,
		backgroundColor: colors.light.gray[100],
		width: 48,
		height: 4,
		borderRadius: 12,
		alignSelf: 'center',
		zIndex: 10
	},
	bottomFadeGradient: {
		position: 'absolute',
		bottom: 0,
		left: 0,
		right: 0,
		width: '100%',
		height: 200,
		zIndex: 1
	}
})
